$ErrorActionPreference='Stop'
$src='C:\Users\Xxkan\actions-runner-heaven\_work\mhw-mods\mhw-mods'
git -C $src fetch origin main fix/legacy-migration-corrupt-cas-20260929
if($LASTEXITCODE -ne 0){ throw 'fetch failed' }
$main=(git -C $src rev-parse origin/main).Trim()
$remote=(git -C $src rev-parse origin/fix/legacy-migration-corrupt-cas-20260929).Trim()
Write-Output "MAIN=$main"
Write-Output "REMOTE_BRANCH_BEFORE=$remote"
if($remote -ne $main){ throw "Recovery precondition changed: branch no longer equals current main" }
$wt="C:\Users\Xxkan\HeavenBridge\work\recover-pr214-$($main.Substring(0,8))"
if(Test-Path $wt){ git -C $src worktree remove --force $wt 2>$null; Remove-Item -Recurse -Force $wt -ErrorAction SilentlyContinue }
git -C $src worktree add --detach $wt $main
if($LASTEXITCODE -ne 0){ throw 'worktree add failed' }
try {
 Push-Location $wt
 foreach($c in @(
  '6e9b3cdf900c7f2dea21b8c2cf4136e805efb061',
  'cd5d2a0c96d3e2cc32edbc8fc5768373c0243112',
  '9c4dcc590b67b800305347869f99432cbc1dd24a',
  '59ce506daf7656d53b3053ec6bfafcdafcbc174c'
 )){
   git cherry-pick $c
   if($LASTEXITCODE -ne 0){ throw "cherry-pick failed $c" }
 }
 $head=(git rev-parse HEAD).Trim()
 Write-Output "RECOVERED_HEAD=$head"
 $env:DOTNET_NOLOGO='1'; $env:DOTNET_CLI_TELEMETRY_OPTOUT='1'
 dotnet restore .\tests\MhwModManager.IntegrationTests\MhwModManager.IntegrationTests.csproj -p:NuGetAudit=false
 if($LASTEXITCODE -ne 0){ throw 'restore failed' }
 dotnet build .\tests\MhwModManager.IntegrationTests\MhwModManager.IntegrationTests.csproj -c Release --no-restore -warnaserror -p:NuGetAudit=false
 if($LASTEXITCODE -ne 0){ throw 'integration build failed' }
 dotnet test .\tests\MhwModManager.IntegrationTests\MhwModManager.IntegrationTests.csproj -c Release --no-build --no-restore -p:NuGetAudit=false --filter "FullyQualifiedName~LegacyMigrationTests"
 if($LASTEXITCODE -ne 0){ throw 'legacy migration regression failed' }
 git diff --check HEAD~4..HEAD
 if($LASTEXITCODE -ne 0){ throw 'diff check failed' }
 git push origin "HEAD:refs/heads/fix/legacy-migration-corrupt-cas-20260929" "--force-with-lease=refs/heads/fix/legacy-migration-corrupt-cas-20260929:$remote"
 if($LASTEXITCODE -ne 0){ throw 'push failed' }
 Write-Output "RECOVERY_PUSHED=$head"
} finally {
 Pop-Location
 git -C $src worktree remove --force $wt 2>$null
}
